#!/usr/bin/env bash
set -euo pipefail
# Apply p2c4-words-grok response-scale fixes. Run from project root (folder with package.json).

if [[ ! -f package.json ]] || [[ ! -d src/lib ]]; then
  echo "ERROR: Run this from the automated-psychometric folder (the one with package.json)."
  exit 1
fi

echo "→ Preparing branch p2c4-words-grok..."
git fetch origin 2>/dev/null || true
git switch p2c4-words 2>/dev/null || git checkout p2c4-words
git pull 2>/dev/null || true
if git show-ref --verify --quiet refs/heads/p2c4-words-grok; then
  git switch p2c4-words-grok
else
  git switch -c p2c4-words-grok
fi

export GROK_PAYLOAD=''

python3 - <<'PY'
import base64, gzip, json, os, pathlib
payload = json.loads(base64.b64decode(os.environ["GROK_PAYLOAD"]))
root = pathlib.Path(".")
for rel, blob in payload["files"].items():
    path = root / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(base64.b64decode(blob))
    print("  wrote", rel)
config = root / "src/components/ConfigScreen.tsx"
config.write_bytes(gzip.decompress(base64.b64decode(payload["config_gz_b64"])))
print("  wrote src/components/ConfigScreen.tsx")
print("OK")
PY

echo ""
echo "→ Staging..."
git add src/lib/responseScaleAnswers.ts \
        src/lib/responseScaleState.ts \
        src/components/ConfigScreen.tsx \
        src/components/ResponseScaleAnswersTable.tsx \
        tests/responseScaleAnswers.test.ts \
        tests/responseScaleState.test.ts
git status --short

echo ""
echo "Done. Next commands:"
echo "  git commit -m \"fix: rare labels as other answers; specials never blank range\""
echo "  npm install"
echo "  npm run dev"
echo ""
echo "Hard-refresh the browser, then re-test Fixture A and fixture_words."
